<?php elseif($tab==='agents'):?><section class="admin-split"><div class="panel"><div class="panel-head"><div><span>AGENT NETWORK</span><h3>Property agents</h3></div></div><?php foreach($agents as $a):?><div class="lead-card"><div><b><?=e($a['name'])?> <?=$a['verified']?'✓':''?></b><small><?=e($a['agency_name']?:'Independent agent')?> · <?=number_format((int)$a['listing_count'])?> listings</small></div><span><?=e($a['phone']?:$a['email'])?></span><span><?=e($a['service_areas']??'')?></span><em class="status <?=$a['verified']?'approved':'pending'?>"><?=$a['verified']?'verified':'standard'?></em></div><?php endforeach;?></div><aside class="panel form-panel"><h3>Create / update agent</h3><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save_agent"><label>User<select name="user_id" required><?php foreach($users as $u):?><option value="<?=(int)$u['id']?>"><?=e($u['name'].' · '.$u['email'])?></option><?php endforeach;?></select></label><label>Agency name<input name="agency_name"></label><label>License / reference<input name="license_no"></label><label>Service areas<input name="service_areas" placeholder="Shahkot, Nankana Road..."></label><label>Languages<input name="languages" placeholder="Urdu, Punjabi, English"></label><label>Bio<textarea name="bio"></textarea></label><div class="checks"><label><input type="checkbox" name="verified" value="1"> Verified agent</label></div><input type="hidden" name="status" value="active"><button class="btn wide">Save agent</button></form></aside></section>
<?php elseif($tab==='analytics'):?><section class="analytics-grid"><div class="panel"><div class="panel-head"><div><span>ENGAGEMENT</span><h3>14-day property activity</h3></div></div><div class="pr560-mini-chart" style="height:220px"><?php foreach($activity as $a):?><i title="<?=e($a['d'].' · '.$a['n'])?>" style="height:<?=max(4,round(((int)$a['n']/$maxAct)*100))?>%"></i><?php endforeach;?></div></div><div class="panel"><div class="panel-head"><div><span>CONVERSION FUNNEL</span><h3>Last 30 days</h3></div></div><div class="funnel"><?php $mx=max(1,...array_map(fn($x)=>(int)$x['n'],$events?:[['n'=>1]]));foreach($events as $ev):?><div><span><?=e(ucwords($ev['event_type']))?></span><i style="width:<?=round(((int)$ev['n']/$mx)*100)?>%"></i><b><?=number_format((int)$ev['n'])?></b></div><?php endforeach;?></div></div></section>
<?php elseif($tab==='settings'):?><section class="panel"><div class="panel-head"><div><span>MODULE CONTROL</span><h3>Property settings</h3></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="settings"><div class="checks"><label><input type="checkbox" name="enabled" value="1" <?=setting_bool('property_v560_enabled',true)?'checked':''?>> Property Pro enabled</label><label><input type="checkbox" name="require_approval" value="1" <?=setting_bool('property_v560_require_approval',true)?'checked':''?>> User submissions require approval</label><label><input type="checkbox" name="guest_inquiries" value="1" <?=setting_bool('property_v560_guest_inquiries',true)?'checked':''?>> Guest inquiries</label><label><input type="checkbox" name="user_submissions" value="1" <?=setting_bool('property_v560_user_submissions',true)?'checked':''?>> User property posting</label><label><input type="checkbox" name="show_map" value="1" <?=setting_bool('property_v560_show_map',true)?'checked':''?>> Property map</label><label><input type="checkbox" name="show_contact" value="1" <?=setting_bool('property_v560_show_contact',true)?'checked':''?>> Public contact actions</label></div><label style="display:block;margin-top:12px">Max gallery images<input type="number" name="max_gallery" value="<?=e(setting('property_v560_max_gallery','12'))?>"></label><button class="btn" style="margin-top:12px">Save settings</button></form></section><?php endif;?></div><?php page_end(); ?>
